```javascript
function findObjectByName(obj, name) {
  let stack = [{node: obj, path: []}];
  while (stack.length > 0) {
    let {node, path} = stack.pop();
    if (node && typeof node === 'object') {
      for (let key in node) {
        if (key === 'name' && node[key] === name) {
          return {foundObject: node, path: [...path, key]};
        }
        if (typeof node[key] === 'object') {
          stack.push({node: node[key], path: [...path, key]});
        }
      }
    }
  }
  return null;
}

