// Calculate Pi using the Leibniz formula
function calculatePi(iterations) {
  let pi = 0;
  let denominator = 1;
  for (let i = 0; i < iterations; i++) {
    if (i % 2 === 0) {
      pi += 1 / denominator;
    } else {
      pi -= 1 / denominator;
    }
    denominator += 2;
  }
  return pi * 4;
}

