    def add_data(self, node_id, data_id, data_size, lifetime_blocks):
        deposit_amount = data_size * lifetime_blocks  # Simplified deposit calculation
        if self.nodes[node_id]['balance'] >= deposit_amount:
            self.nodes[node_id]['balance'] -= deposit_amount
            self.data[data_id] = {
                'owner': node_id,
                'size': data_size,
                'lifetime': lifetime_blocks,
                'deposit': deposit_amount,
                'host_nodes': [node_id],
                'creation_block': self.current_block
            }
        else:
            raise Exception("Insufficient balance")

    def host_data(self, node_id, data_id):
        if data_id in self.data:
            self.data[data_id]['host_nodes'].append(node_id)

    def access_data(self, node_id, data_id):
        if data_id in self.data:
            owner = self.data[data_id]['owner']
            fee = self.data[data_id]['size'] * 0.01  # Simplified fee
            if self.nodes[node_id]['balance'] >= fee:
                self.nodes[node_id]['balance'] -= fee
                self.nodes[owner]['balance'] += fee
            else:
                raise Exception("Insufficient balance to pay fee")

    def delete_data(self, node_id, data_id):
        if data_id in self.data and self.data[data_id]['owner'] == node_id:
            deposit = self.data[data_id]['deposit']
            self.nodes[node_id]['balance'] += deposit
            del self.data[data_id]

    def next_block(self):
        self.current_block += 1
        # Remove expired data
        for data_id in list(self.data.keys()):
            data = self.data[data_id]
            if self.current_block - data['creation_block'] >= data['lifetime']:
                # Distribute deposit among hosting nodes
                share = data['deposit'] / len(data['host_nodes'])
                for node in data['host_nodes']:
