out vec4 FragColor;
void main()
{
    // Raycasting implementation
    vec3 rayOrigin = vec3(0.0, 0.0, 0.0);
    vec3 rayDirection = normalize(vec3(gl_FragCoord.xy, -1.0));
    // Simplified raycast for a sphere at (0,0,-5) with radius 1
    vec3 sphereCenter = vec3(0.0, 0.0, -5.0);
    float radius = 1.0;
    vec3 oc = rayOrigin - sphereCenter;
    float a = dot(rayDirection, rayDirection);
    float b = 2.0 * dot(oc, rayDirection);
    float c = dot(oc, oc) - radius * radius;
    float discriminant = b * b - 4.0 * a * c;
    if(discriminant < 0.0)
        FragColor = vec4(0.0, 0.0, 0.0, 1.0); // background
    else
    {
        float t = (-b - sqrt(discriminant)) / (2.0 * a);
        vec3 hitPoint = rayOrigin + t * rayDirection;
        vec3 normal = normalize(hitPoint - sphereCenter);
        float lighting = max(dot(normal, vec3(0.0, 0.0, -1.0)), 0.0);
        FragColor = vec4(lighting, lighting, lighting, 1.0);
    }
}

