function [x_est, P_est] = kalman_filter(z, A, C, Q, R, x0, P0)
  % z: measurements
  % A: state transition matrix
  % C: measurement matrix
  % Q: process noise covariance
  % R: measurement noise covariance
  % x0: initial state estimate
  % P0: initial estimate covariance
  n = length(z);
  x_est = zeros(size(x0,1), n);
  P_est = zeros(size(x0,1), size(x0,1), n);
  x_est(:,1) = x0;
  P_est(:,:,1) = P0;
  for k = 2:n
    % Prediction
    x_pred = A * x_est(:,k-1);
    P_pred = A * P_est(:,:,k-1) * A' + Q;
    % Update
    K = P_pred * C' / (C * P_pred * C' + R);
    x_est(:,k) = x_pred + K * (z(k) - C * x_pred);
    P_est(:,:,k) = (eye(size(K,1)) - K * C) * P_pred;
  end
end

