kernel void gaussian_blur(texture2d<float, access::read> inTexture [[texture(0)]],
                          texture2d<float, access::write> outTexture [[texture(1)]],
                          constant float *kernel [[buffer(0)]],
                          uint2 gid [[thread_position_in_grid]]) {
    int2 size = int2(inTexture.get_width(), inTexture.get_height());
    if (gid.x >= size.x || gid.y >= size.y) return;

    float4 color = float4(0.0);
    int kernelRadius = 2; // for a 5x5 kernel
    int kernelSize = 2 * kernelRadius + 1;
    for (int y = -kernelRadius; y <= kernelRadius; y++) {
        for (int x = -kernelRadius; x <= kernelRadius; x++) {
            int2 coord = int2(gid) + int2(x, y);
            coord.x = clamp(coord.x, 0, size.x - 1);
            coord.y = clamp(coord.y, 0, size.y - 1);
            float weight = kernel[(y + kernelRadius) * kernelSize + (x + kernelRadius)];
            color += inTexture.read(uint2(coord)) * weight;
        }
    }
    outTexture.write(color, gid);
}
