// Simple RNN implementation in TypeScript
class SimpleRNN {
  private weightsInputHidden: number[][];
  private weightsHiddenOutput: number[][];
  private hiddenState: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    // Initialize weights with small random values
    this.weightsInputHidden = Array.from({ length: inputSize }, () => Array.from({ length: hiddenSize }, () => Math.random() * 0.1));
    this.weightsHiddenOutput = Array.from({ length: hiddenSize }, () => Array.from({ length: outputSize }, () => Math.random() * 0.1));
    this.hiddenState = Array.from({ length: hiddenSize }, () => 0);
  }

  // Activation function (tanh)
  private activate(x: number): number {
    return Math.tanh(x);
  }

  // Forward pass for one time step
  public step(input: number[]): {
    hiddenState: number[];
    output: number[];
  } {
    // Compute new hidden state
    const newHiddenState = this.weightsInputHidden.reduce((acc, weights, i) => {
      const inputVal = input[i];
      return acc.map((sum, j) => sum + weights[j] * inputVal);
    }, Array.from({ length: this.hiddenState.length }, () => 0));

    // Add previous hidden state contribution
    for (let j = 0; j < newHiddenState.length; j++) {
      for (let i = 0; i < this.hiddenState.length; i++) {
        newHiddenState[j] += this.weightsHiddenOutput[i][j] * this.hiddenState[i];
      }
    }

    // Apply activation
    this.hiddenState = newHiddenState.map(this.activate);

    // Compute output
    const output = this.weightsHiddenOutput.reduce((acc, weights, i) => {
      return acc.map((sum, j) => sum + weights[j] * this.hiddenState[j]);
    }, Array.from({ length: this.weightsHiddenOutput[0].length }, () => 0));

    return {
      hiddenState: this.hiddenState,
      output: output,
    };
  }
}

