function findEntity(json, entityKey) {
  const results = [];
  const path = [];

  function recurse(obj) {
    if (typeof obj !== 'object' || obj === null) {
      return;
    }
    for (const key in obj) {
      if (key === entityKey) {
        results.push({ value: obj[key], location: [...path, key] });
      }
      path.push(key);
      recurse(obj[key]);
      path.pop();
    }
  }

  recurse(json);
  return results;
}

