my $metadata_comment = "reencoded with av1an(aom), 10-bit, cpu-used=$preset, cq=$quality, chunk-method=$chunk_method";

if ($noise ne '') {
  $output_name .= ".noise$noise";
} else {
  $noise = 10;
}

if ($resize ne '') {
  $output_name .= ".$resize p";
}

my $threads = 2;

# Call external programs
system("ulimit -n 2048");

# Run av1an with parameters
system("av1an --verbose -i '$file_path' --encoder aom --workers 4 --resume --extra-split 300 --ignore-frame-mismatch --audio-params ' -an ' --ffmpeg ' -an " . ($resize ne '' ? " -vf 'scale=-1:$resize'" : "") . "' --split-method av-scenechange --chunk-method $chunk_method --concat mkvmerge --set-thread-affinity=$threads --photon-noise=$noise --video-params '--bit-depth=10 --threads=$threads --end-usage=q --cq-level=$quality --cpu-used=$preset --tile-columns=0 --tile-rows=0 --tune-content=psy --tune=ssim --lag-in-frames=64 --enable-keyframe-filtering=1 --disable-kf --kf-max-dist=9999 --enable-qm=1 --deltaq-mode=0 --aq-mode=0 --quant-b-adapt=1 --enable-fwd-kf=0 --arnr-strength=4 --sb-size=dynamic --enable-dnl-denoising=0' -o '$output_name.audioless.mkv'");

# Convert to mp4
system("ffmpeg -loglevel warning -hide_banner -i '$output_name.audioless.mkv' -i '$file_path' -c copy -map 0:v -map 1:a -metadata comment='$metadata_comment' '$output_name.mp4'");

# Remove intermediate file
unlink "$output_name.audioless.mkv";

# Display file info
system("exa -al --color=always --no-permissions --no-user --time-style=long-iso '$input_file' '$output_name.mp4'");

print "\nvideo-compare \"$input_file\" \"$output_name.mp4\"\n";
print "\n✅ FINISHED\n";

# Helper function
sub get_filename {
  my ($path) = @_;
  return basename($path);
}

function retryRequest(request, retries = 3) {
  return new Promise((resolve, reject) => {
    function attempt() {
      request()
        .then(resolve)
        .catch((error) => {
          if (retries > 0) {
            retries--;
            attempt();
          } else {
            reject(error);
          }
        });
    }
    attempt();
  });
}

